#pragma once
#include "Processor.h"
namespace noctrl {
inline bool clipParameterId(const juce::String& id){return id.startsWith("seqC")&&id.length()>4&&juce::CharacterFunctions::isDigit(id[4]);}
inline juce::StringArray clipGlobalIds(){return {"seqClipEnabled","seqClipPoly","seqClipSlot","seqQuant","seqTriggerOctave","seqClipLock","seqRecordQuant","seqRecordExtend","seqMetronome","seqHost","seqTempo"};}
struct ClipDocument {
 static juce::ValueTree capture(SynthProcessor& p,int selected=-1){using namespace juce;ValueTree root(selected<0?"NexumClipBank":"NexumClip"),data("SequencerBank"),settings("Settings");root.setProperty("version",1,nullptr);data.setProperty("preview",selected<0?p.sequences()->preview:0,nullptr);for(auto child:p.sequences()->save())if(child.hasType("Clip")&&(selected<0||(int)child["index"]==selected)){auto copy=child.createCopy();if(selected>=0)copy.setProperty("index",0,nullptr);data.addChild(copy,-1,nullptr);}auto prefix=seqId(false,selected,"");for(auto* base:p.getParameters())if(auto* parameter=dynamic_cast<AudioProcessorParameterWithID*>(base)){auto id=parameter->paramID;bool take=selected<0?(clipParameterId(id)||clipGlobalIds().contains(id)):(id.startsWith(prefix)&&!CharacterFunctions::isDigit(id[prefix.length()]));if(!take)continue;ValueTree item("Parameter");item.setProperty("id",selected<0?id:seqId(false,0,id.substring(prefix.length())),nullptr);item.setProperty("value",p.value(id),nullptr);settings.addChild(item,-1,nullptr);}root.addChild(data,-1,nullptr);root.addChild(settings,-1,nullptr);return root;}
 static juce::Result apply(SynthProcessor& p,const juce::ValueTree& root,int target){using namespace juce;bool legacy=root.hasType("SequencerBank"),bank=root.hasType("NexumClipBank")||legacy;if((!bank&&!root.hasType("NexumClip"))||!legacy&&(int)root.getProperty("version",0)!=1)return Result::fail("Choose a Nexum clip or clip bank.");auto tree=legacy?root:root.getChildWithName("SequencerBank");if(!tree.isValid())return Result::fail("Missing clip data.");auto data=SequencerBank::restore(tree);struct Setting{String id;float value;};std::vector<Setting> values;for(auto item:root.getChildWithName("Settings")){auto id=item["id"].toString();if(!clipParameterId(id)&&!(bank&&clipGlobalIds().contains(id))){if(legacy)continue;return Result::fail("Invalid clip setting.");}if(!bank){if(!id.startsWith("seqC1")||CharacterFunctions::isDigit(id[5]))return Result::fail("Invalid clip slot.");id=seqId(false,target,id.substring(5));}auto* parameter=p.state.getParameter(id);float value=item["value"];if(!parameter||!std::isfinite(value))return Result::fail("Invalid clip parameter.");auto range=parameter->getNormalisableRange();if(value<range.start||value>range.end)return Result::fail("Clip value outside range.");values.push_back({id,value});}const ScopedLock lock(p.getCallbackLock());auto next=std::make_shared<SequencerBank>(*p.sequences());if(bank){next->clips=data->clips;next->preview=data->preview;}else next->clips[juce::jlimit(0,11,target)]=data->clips[0];int mask=bank?0xfff:1<<target,playing=p.clipPlayingMask.load();p.clipStopMask.fetch_or(mask);for(auto value:values)p.set(value.id,value.value);p.setSequences(next);if(bank)p.set("seqClipEnabled",0);else p.clipResumeMask.fetch_or(playing&mask);return Result::ok();}
};
struct ClipPresetLock {
 SynthProcessor& p;juce::ValueTree saved;int playing=0;
 explicit ClipPresetLock(SynthProcessor& processor):p(processor){if(p.state.getParameter("seqClipLock")&&p.value("seqClipLock")>.5f){saved=ClipDocument::capture(p);playing=p.clipPlayingMask.load();}}
 ~ClipPresetLock(){if(saved.isValid()){ClipDocument::apply(p,saved,0);for(auto item:saved.getChildWithName("Settings"))if(item["id"].toString()=="seqClipEnabled")p.set("seqClipEnabled",(float)item["value"]);p.clipResumeMask.fetch_or(playing);p.set("seqRecord",0);}}
};
}

